@mcp.tool()
def elementor_landing_page_create(
    title: str,
    content: str = None,
    slug: str = None,
    status: str = "draft",
) -> dict:
    """Create an Elementor landing page (no header/footer, full-width)"""
    body = {"title": title, "status": status, "template": "elementor_canvas"}
    if content: body["content"] = content
    if slug: body["slug"] = slug
    return _wp().post("/wp/v2/pages", json=body)

@mcp.tool()
def elementor_landing_page_list(
    per_page: int = 50,
    status: str = "any",
) -> dict:
    """List all Elementor landing pages"""
    params = {"per_page": per_page, "context": "edit"}
    if status not in (None, "any"):
        params["status"] = status
    pages = _wp().get("/wp/v2/pages", params=params)
    items = _elementor_flatten_items(pages)
    landing_pages = [page for page in items if isinstance(page, dict) and page.get("template") == "elementor_canvas"]
    return {
        "data": landing_pages,
        "count": len(landing_pages),
        "status": status,
        "template": "elementor_canvas",
    }

