@mcp.tool()
def elementor_container_create(
    page_id: int,
    container_type: str = "flex",
    position: int = None,
    settings: dict = None,
) -> dict:
    """Create a flex or grid container element in Elementor page data"""
    _, structure = _elementor_get_document_structure(page_id, "pages")
    container_settings = dict(settings or {})
    container_settings.setdefault("container_type", container_type)
    structure.insert(_elementor_resolve_insert_index(position, len(structure)), _elementor_make_container(container_settings))
    return _elementor_update_document_structure(page_id, "pages", structure)

@mcp.tool()
def elementor_container_set_layout(
    page_id: int,
    container_id: str,
    layout: dict,
) -> dict:
    """Set flex/grid layout properties on an Elementor container"""
    _, structure = _elementor_get_document_structure(page_id, "pages")
    found = _elementor_find_element(structure, container_id)
    if not found:
        raise ValueError(f"Container '{container_id}' not found")
    element = found["element"]
    if element.get("elType") != "container":
        raise ValueError(f"Element '{container_id}' is not a container")
    element["settings"] = {**(element.get("settings") or {}), **(layout or {})}
    return _elementor_update_document_structure(page_id, "pages", structure)

@mcp.tool()
def elementor_build_full_page(
    page_id: int,
    sections: list,
    page_type: str = "pages",
) -> dict:
    """Build a complete Elementor page from supported section briefs or native Elementor element JSON."""
    return elementor_build_page(
        page_id=page_id,
        sections=sections,
        page_type=page_type,
        replace_existing=True,
    )

@mcp.tool()
def elementor_get_page_structure(
    page_id: int,
    page_type: str = "pages",
) -> dict:
    """Get the full Elementor section/column/widget tree of a page"""
    document = _elementor_format_document(_elementor_get_document(page_id, page_type))
    return {
        "id": document.get("id"),
        "type": document.get("type"),
        "elementor_enabled": document.get("elementor_enabled"),
        "structure": document.get("elementor_data") or [],
    }

@mcp.tool()
def elementor_clear_page(
    page_id: int,
    page_type: str = "pages",
) -> dict:
    """Remove all Elementor content from a page (empty canvas)"""
    collection = _elementor_content_collection(page_type)
    updated = _wp().post(
        f"/wp/v2/{collection}/{page_id}",
        json={"meta": {"_elementor_data": "[]", "_elementor_edit_mode": "builder"}},
    )
    return _elementor_format_document(updated)

@mcp.tool()
def elementor_add_section(
    page_id: int,
    page_type: str = "pages",
    position: str = "last",
    columns: int = 1,
    background_color: str = None,
    background_image_url: str = None,
    padding_top: str = "50",
    padding_bottom: str = "50",
    min_height: str = None,
    content_width: str = None,
    css_class: str = None,
    css_id: str = None,
    html_tag: str = None,
    column_gap: str = None,
    reverse_on_mobile: bool = None,
    entrance_animation: str = None,
) -> dict:
    """Add a new section (with columns) to an Elementor page"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    section_settings = {
        "background_color": background_color,
        "background_image_url": background_image_url,
        "padding": {"top": padding_top, "bottom": padding_bottom},
        "min_height": min_height,
        "content_width": content_width,
        "css_classes": css_class,
        "css_id": css_id,
        "html_tag": html_tag,
        "column_gap": column_gap,
        "reverse_mobile": reverse_on_mobile,
        "entrance_animation": entrance_animation,
    }
    section = _elementor_make_section(columns=columns, settings={k: v for k, v in section_settings.items() if v is not None})
    structure.insert(_elementor_resolve_insert_index(position, len(structure)), section)
    return _elementor_update_document_structure(page_id, page_type, structure)

@mcp.tool()
def elementor_delete_section(
    page_id: int,
    section_id: str,
    page_type: str = "pages",
) -> dict:
    """Delete a section from an Elementor page by its ID"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    found = _elementor_find_element(structure, section_id)
    if not found:
        raise ValueError(f"Section '{section_id}' not found")
    if found["element"].get("elType") != "section":
        raise ValueError(f"Element '{section_id}' is not a section")
    found["siblings"].pop(found["index"])
    return _elementor_update_document_structure(page_id, page_type, structure)

@mcp.tool()
def elementor_update_section_settings(
    page_id: int,
    section_id: str,
    settings: dict,
    page_type: str = "pages",
) -> dict:
    """Update styling/settings of an existing section"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    found = _elementor_find_element(structure, section_id)
    if not found:
        raise ValueError(f"Section '{section_id}' not found")
    if found["element"].get("elType") != "section":
        raise ValueError(f"Element '{section_id}' is not a section")
    found["element"]["settings"] = {**(found["element"].get("settings") or {}), **(settings or {})}
    return _elementor_update_document_structure(page_id, page_type, structure)

