@mcp.tool()
def elementor_preset_hero(
    page_id: int,
    heading: str,
    page_type: str = "pages",
    subtext: str = None,
    cta_text: str = None,
    cta_url: str = None,
    bg_color: str = "#1e1e2e",
    bg_image_url: str = None,
    heading_color: str = "#ffffff",
    text_color: str = "#ffffff",
    padding_top: str = "100",
    padding_bottom: str = "100",
) -> dict:
    """Add a full hero section (heading + subtext + CTA button) to a page"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    section = _elementor_make_section(
        columns=1,
        settings={
            "background_color": bg_color,
            "background_image_url": bg_image_url,
            "padding": {"top": padding_top, "bottom": padding_bottom},
        },
    )
    _elementor_append_widget_to_section(section, "heading", {"text": heading, "tag": "h1", "align": "center", "color": heading_color})
    if subtext is not None:
        _elementor_append_widget_to_section(section, "text-editor", {"content": subtext, "align": "center", "text_color": text_color})
    if cta_text is not None and cta_url is not None:
        _elementor_append_widget_to_section(section, "button", {"text": cta_text, "link_url": cta_url, "align": "center"})
    structure.append(section)
    updated = _elementor_update_document_structure(page_id, page_type, structure)
    return {"page": updated, "section_ids": [section["id"]]}

@mcp.tool()
def elementor_preset_features(
    page_id: int = None,
    page_type: str = "pages",
    heading: str = None,
    cards: list = None,
    bg_color: str = "#ffffff",
) -> dict:
    """Add a Features/Services cards section (icon boxes in columns) to a page"""
    if page_id is None:
        raise ValueError("page_id is required")
    _, structure = _elementor_get_document_structure(page_id, page_type)
    section_ids: list[str] = []
    cards_list = list(cards or [])
    if heading is not None:
        heading_section = _elementor_make_section(columns=1, settings={"background_color": bg_color, "padding": {"top": "70", "bottom": "20"}})
        _elementor_append_widget_to_section(heading_section, "heading", {"text": heading, "tag": "h2", "align": "center"})
        structure.append(heading_section)
        section_ids.append(heading_section["id"])
    if cards_list:
        cards_section = _elementor_make_section(columns=max(1, len(cards_list)), settings={"background_color": bg_color, "padding": {"top": "20", "bottom": "70"}})
        for index, card in enumerate(cards_list):
            item = dict(card or {})
            widget_settings = {k: v for k, v in {
                "icon": item.get("icon"),
                "library": item.get("library"),
                "title": item.get("title"),
                "description": item.get("description"),
                "icon_color": item.get("icon_color"),
                "icon_size": item.get("icon_size"),
                "align": item.get("align"),
                "view": item.get("view"),
                "link_url": item.get("link_url"),
                "css_class": item.get("css_class"),
            }.items() if v is not None}
            _elementor_append_widget_to_section(cards_section, "icon-box", widget_settings, index)
        structure.append(cards_section)
        section_ids.append(cards_section["id"])
    updated = _elementor_update_document_structure(page_id, page_type, structure)
    return {"page": updated, "section_ids": section_ids}

