@mcp.tool()
def elementor_preset_full_landing_page(
    page_id: int = None,
    page_type: str = "pages",
    hero: dict = None,
    features: dict = None,
    testimonials: dict = None,
    cta: dict = None,
) -> dict:
    """Build a complete landing page with hero + features + testimonials + CTA in one call"""
    if page_id is None:
        raise ValueError("page_id is required")
    elementor_clear_page(page_id, page_type)
    applied: dict[str, Any] = {}
    if hero is not None:
        hero_payload = dict(hero)
        hero_payload.pop("page_id", None)
        hero_payload.pop("page_type", None)
        applied["hero"] = elementor_preset_hero(page_id=page_id, page_type=page_type, **hero_payload)
    if features is not None:
        features_payload = dict(features)
        features_payload.pop("page_id", None)
        features_payload.pop("page_type", None)
        applied["features"] = elementor_preset_features(page_id=page_id, page_type=page_type, **features_payload)
    if testimonials is not None:
        testimonials_payload = dict(testimonials)
        testimonials_payload.pop("page_id", None)
        testimonials_payload.pop("page_type", None)
        applied["testimonials"] = elementor_preset_testimonials(page_id=page_id, page_type=page_type, **testimonials_payload)
    if cta is not None:
        cta_payload = dict(cta)
        cta_payload.pop("page_id", None)
        cta_payload.pop("page_type", None)
        applied["cta"] = elementor_preset_cta(page_id=page_id, page_type=page_type, **cta_payload)
    return {"page": elementor_get_page_data(page_id, page_type), "applied": applied}

@mcp.tool()
def elementor_remove_widget(
    page_id: int,
    widget_id: str,
    page_type: str = "pages",
) -> dict:
    """Remove a specific widget from an Elementor page by its widget ID"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    found = _elementor_find_element(structure, widget_id)
    if not found:
        raise ValueError(f"Widget '{widget_id}' not found")
    if found["element"].get("elType") != "widget":
        raise ValueError(f"Element '{widget_id}' is not a widget")
    found["siblings"].pop(found["index"])
    return _elementor_update_document_structure(page_id, page_type, structure)

@mcp.tool()
def elementor_update_widget_settings(
    page_id: int,
    widget_id: str,
    settings: dict,
    page_type: str = "pages",
) -> dict:
    """Update settings of a specific widget on a page by its widget ID"""
    _, structure = _elementor_get_document_structure(page_id, page_type)
    found = _elementor_find_element(structure, widget_id)
    if not found:
        raise ValueError(f"Widget '{widget_id}' not found")
    if found["element"].get("elType") != "widget":
        raise ValueError(f"Element '{widget_id}' is not a widget")
    found["element"]["settings"] = {**(found["element"].get("settings") or {}), **(settings or {})}
    return _elementor_update_document_structure(page_id, page_type, structure)

