@mcp.tool()
def elementor_detect() -> dict:
    """Detect Elementor and Elementor Pro plugin status via the plugins controller when available."""
    try:
        plugins = _elementor_flatten_items(_wp().get("/wp/v2/plugins", params={"context": "edit", "per_page": 100}))
    except requests.HTTPError as exc:
        return _unsupported_from_http(exc, "wp/v2 plugins controller")
    elementor = _elementor_match_plugin(plugins, "elementor/elementor.php")
    elementor_pro = _elementor_match_plugin(plugins, "elementor-pro/elementor-pro.php")
    return {
        "active": bool(elementor and elementor.get("status") == "active"),
        "pro_active": bool(elementor_pro and elementor_pro.get("status") == "active"),
        "elementor": elementor,
        "elementor_pro": elementor_pro,
    }

@mcp.tool()
def elementor_pro_detect() -> dict:
    """Detect whether Elementor Pro is installed and active."""
    detected = elementor_detect()
    return {
        "active": detected.get("pro_active", False),
        "plugin": detected.get("elementor_pro"),
        "elementor_active": detected.get("active", False),
    }

@mcp.tool()
def elementor_rest_capabilities() -> dict:
    """Check which Elementor-related REST surfaces are reachable on the connected WordPress site."""
    capabilities: dict[str, Any] = {}
    try:
        capabilities["plugins_controller"] = {
            "supported": True,
            "result_count": len(_elementor_flatten_items(_wp().get("/wp/v2/plugins", params={"context": "edit", "per_page": 5}))),
        }
    except requests.HTTPError as exc:
        capabilities["plugins_controller"] = _unsupported_from_http(exc, "wp/v2 plugins controller")
    try:
        library = _wp().get("/wp/v2/elementor_library", params={"per_page": 5})
        capabilities["elementor_library"] = {
            "supported": True,
            "result_count": len(_elementor_flatten_items(library)),
        }
    except requests.HTTPError as exc:
        capabilities["elementor_library"] = _unsupported_from_http(exc, "wp/v2 elementor_library controller")
    return capabilities

@mcp.tool()
def elementor_validate_page_data(elementor_data: Any) -> dict:
    """Validate Elementor JSON before attempting to write it to a page."""
    encoded = _elementor_validate_data_json(elementor_data)
    parsed = json.loads(encoded)
    structure = _elementor_normalize_structure(parsed)
    return {
        "valid": True,
        "root_elements": len(structure),
        "widget_count": _elementor_count_widgets(structure),
        "encoded_length": len(encoded),
    }

