@mcp.tool()
def elementor_backup_page_data(
    id: int,
    type: str = "page",
) -> dict:
    """Capture current Elementor page meta so it can be restored later."""
    document = _elementor_get_document(id, type)
    meta = document.get("meta") or {}
    return {
        "page": _elementor_format_document(document),
        "backup": {
            "id": document.get("id"),
            "type": document.get("type"),
            "elementor_data": meta.get("_elementor_data"),
            "page_settings": meta.get("_elementor_page_settings"),
            "edit_mode": meta.get("_elementor_edit_mode"),
        },
    }

@mcp.tool()
def elementor_update_page_data(
    id: int,
    elementor_data: str,
    type: str = "page",
    page_settings: dict = None,
) -> dict:
    """Replace native Elementor JSON for a page/post. Descriptive section briefs are not accepted here."""
    collection = _elementor_content_collection(type)
    body = {
        "meta": {
            "_elementor_data": _elementor_validate_data_json(elementor_data),
            "_elementor_edit_mode": "builder",
        }
    }
    if page_settings is not None:
        body["meta"]["_elementor_page_settings"] = _elementor_encode_json_blob(page_settings, "page_settings")
    updated = _wp().post(f"/wp/v2/{collection}/{id}", json=body)
    return _elementor_format_document(updated)

@mcp.tool()
def elementor_restore_page_data(
    id: int,
    backup: dict,
    type: str = "page",
) -> dict:
    """Restore Elementor page meta from a prior backup payload."""
    collection = _elementor_content_collection(type)
    meta: dict[str, Any] = {}
    if "elementor_data" in backup and backup["elementor_data"] is not None:
        meta["_elementor_data"] = _elementor_validate_data_json(backup["elementor_data"])
    if "page_settings" in backup and backup["page_settings"] is not None:
        meta["_elementor_page_settings"] = _elementor_encode_json_blob(backup["page_settings"], "page_settings")
    if "edit_mode" in backup:
        meta["_elementor_edit_mode"] = backup["edit_mode"]
    updated = _wp().post(f"/wp/v2/{collection}/{id}", json={"meta": meta})
    return _elementor_format_document(updated)

