@mcp.tool()
def elementor_create_page_with_template(
    title: str,
    template_id: int,
    slug: str = None,
    status: str = "draft",
) -> dict:
    """Create a new page and apply an Elementor template to it"""
    template = _elementor_format_document(_elementor_get_library_document(template_id))
    page_body = {"title": title, "status": status}
    if slug is not None:
        page_body["slug"] = slug
    page = _wp().post("/wp/v2/pages", json=page_body)
    updated_page = elementor_update_page_data(
        page["id"],
        template.get("elementor_data") or [],
        type="page",
        page_settings=template.get("page_settings"),
    )
    return {
        "page": updated_page,
        "source_template_id": template_id,
    }

