@mcp.tool()
def sitegen_setup_menu(
    page_ids: list,
    menu_name: str = "Main Menu",
    location: str = "primary",
) -> dict:
    """Auto-create main navigation menu from page list"""
    wp = _wp()
    menu = wp.post("/wp/v2/menus", json={"name": menu_name, "slug": menu_name.lower().replace(" ", "-")})
    menu_id = menu.get("id")
    if not menu_id:
        return menu
    items = []
    for i, page_id in enumerate(page_ids or [], start=1):
        try:
            item = wp.post("/wp/v2/menu-items", json={"object": "page", "object_id": page_id, "type": "post_type", "menus": menu_id, "menu_order": i})
            items.append(item)
        except Exception as exc:
            items.append({"page_id": page_id, "error": str(exc)})
    return {"menu": menu, "items": items}

