@mcp.tool()
def elementor_add_container(
    post_id: int,
    direction: str = "row",
    content_width: str = "boxed",
    align_items: str = "stretch",
    justify_content: str = None,
    gap: str = None,
    background_color: str = None,
    padding: dict = None,
    min_height: str = None,
    insert_position: int = None,
) -> dict:
    """Add a Flexbox Container to an Elementor page (Elementor 3.6+ containers)"""
    _, structure = _elementor_get_document_structure(post_id, "pages")
    container_settings = {
        "direction": direction,
        "content_width": content_width,
        "align_items": align_items,
        "justify_content": justify_content,
        "gap": gap,
        "background_color": background_color,
        "padding": padding,
        "min_height": min_height,
    }
    structure.insert(
        _elementor_resolve_insert_index(insert_position, len(structure)),
        _elementor_make_container({k: v for k, v in container_settings.items() if v is not None}),
    )
    return _elementor_update_document_structure(post_id, "pages", structure)

