@mcp.tool()
def elementor_update_widget(
    post_id: int,
    element_id: str,
    settings: dict,
) -> dict:
    """Update settings of an existing Elementor widget by its element ID"""
    _, structure = _elementor_get_document_structure(post_id, "pages")
    found = _elementor_find_element(structure, element_id)
    if not found:
        raise ValueError(f"Widget '{element_id}' not found")
    if found["element"].get("elType") != "widget":
        raise ValueError(f"Element '{element_id}' is not a widget")
    found["element"]["settings"] = {**(found["element"].get("settings") or {}), **(settings or {})}
    return _elementor_update_document_structure(post_id, "pages", structure)

@mcp.tool()
def elementor_delete_element(
    post_id: int,
    element_id: str,
) -> dict:
    """Delete an element (section, column, widget) from an Elementor page by element ID"""
    _, structure = _elementor_get_document_structure(post_id, "pages")
    found = _elementor_find_element(structure, element_id)
    if not found:
        raise ValueError(f"Element '{element_id}' not found")
    found["siblings"].pop(found["index"])
    return _elementor_update_document_structure(post_id, "pages", structure)

@mcp.tool()
def elementor_duplicate_element(
    post_id: int,
    element_id: str,
) -> dict:
    """Duplicate an element (section, column, or widget) on an Elementor page"""
    _, structure = _elementor_get_document_structure(post_id, "pages")
    found = _elementor_find_element(structure, element_id)
    if not found:
        raise ValueError(f"Element '{element_id}' not found")
    found["siblings"].insert(found["index"] + 1, _elementor_clone_with_new_ids(found["element"]))
    return _elementor_update_document_structure(post_id, "pages", structure)

