@mcp.tool()
def elementor_build_page(
    page_id: int,
    sections: list,
    page_type: str = "pages",
    design_theme: str = "modern_light",
    replace_existing: bool = True,
) -> dict:
    """Build a complete Elementor page from supported section briefs or native Elementor element JSON."""
    sections_list = list(sections or [])
    if _elementor_is_native_structure(sections_list):
        if replace_existing:
            updated = elementor_update_page_data(page_id, sections_list, type=page_type)
            return {
                "page": updated,
                "applied": [{"type": "native-elementor-json", "element_count": len(sections_list)}],
                "applied_to_page": True,
            }
        result = _elementor_insert_elements(page_id, page_type, sections_list, "end")
        result["applied"] = [{"type": "native-elementor-json", "element_count": len(sections_list)}]
        return result

    if replace_existing:
        elementor_clear_page(page_id, page_type)

    section_builders = {
        "hero": elementor_add_hero_section,
        "features": elementor_add_features_section,
        "stats": elementor_add_stats_section,
        "testimonials": elementor_add_testimonials_section,
        "pricing": elementor_add_pricing_section,
        "cta": elementor_add_cta_section,
        "faq": elementor_add_faq_section,
        "team": elementor_add_team_section,
        "text-media": elementor_add_text_media_section,
        "media-text": elementor_add_text_media_section,
        "logo-bar": elementor_add_logo_bar,
        "logos": elementor_add_logo_bar,
    }
    applied: list[dict[str, Any]] = []
    for index, raw_section in enumerate(sections_list):
        if not isinstance(raw_section, dict):
            raise ValueError(f"Section #{index + 1} must be an object")
        payload = dict(raw_section)
        raw_type = payload.pop("type", None) or payload.pop("section_type", None) or payload.pop("kind", None)
        section_type = _elementor_section_type_key(raw_type)
        if not section_type:
            raise ValueError(f"Section #{index + 1} must include a type")
        builder = section_builders.get(section_type)
        if builder is None:
            supported = ", ".join(sorted(set(section_builders.keys())))
            raise ValueError(f"Unsupported section type '{raw_type}'. Supported types: {supported}")
        payload.pop("page_id", None)
        payload.pop("page_type", None)
        payload.setdefault("design_theme", design_theme)
        payload.setdefault("position", "end")
        if section_type == "hero":
            if "headline" not in payload and "title" in payload:
                payload["headline"] = payload.pop("title")
            if "subheadline" not in payload and "subtext" in payload:
                payload["subheadline"] = payload.pop("subtext")
        elif section_type in {"features", "stats", "testimonials", "pricing", "cta", "faq", "team"}:
            if "title" not in payload and "heading" in payload:
                payload["title"] = payload.pop("heading")
        elif section_type in {"text-media", "media-text"}:
            if "headline" not in payload and "title" in payload:
                payload["headline"] = payload.pop("title")
            if "body" not in payload and "content" in payload:
                payload["body"] = payload.pop("content")
        result = builder(page_id=page_id, page_type=page_type, **payload)
        applied.append({
            "type": section_type,
            "section_ids": result.get("section_ids", []),
            "applied_to_page": result.get("applied_to_page", False),
        })
    return {
        "page": elementor_get_page_data(page_id, page_type),
        "applied": applied,
        "applied_to_page": True,
    }

@mcp.tool()
def elementor_add_hero_section(
    page_id: int,
    headline: str,
    page_type: str = "pages",
    style: str = "centered",
    subheadline: str = None,
    description: str = None,
    badge: str = None,
    cta_text: str = None,
    cta_url: str = None,
    cta_secondary_text: str = None,
    cta_secondary_url: str = None,
    bg_color: str = None,
    bg_gradient_from: str = None,
    bg_gradient_to: str = None,
    bg_image: str = None,
    text_color: str = None,
    image_url: str = None,
    height: str = "100vh",
    points: list = None,
    design_theme: str = "modern_dark",
    position: str = "end",
) -> dict:
    """Add a beautiful hero section to an Elementor page. Style: 'centered' (full-width center-aligned) or 'split' (text left, image right)"""
    base_bg = bg_color or bg_gradient_from or ("#111827" if "dark" in design_theme else "#ffffff")
    base_text = text_color or ("#ffffff" if "dark" in design_theme else "#111827")
    section_settings = {
        "background_color": base_bg,
        "background_image_url": bg_image,
        "padding": {"top": "100", "bottom": "100"},
        "min_height": height,
    }
    section = _elementor_make_section(columns=2 if style == "split" and image_url else 1, settings={k: v for k, v in section_settings.items() if v is not None})
    text_column = 0
    image_column = 1 if len(section.get("elements", [])) > 1 else 0
    if badge is not None:
        _elementor_append_widget_to_section(section, "heading", {"text": badge, "tag": "h6", "color": base_text}, text_column)
    _elementor_append_widget_to_section(section, "heading", {"text": headline, "tag": "h1", "color": base_text}, text_column)
    text_parts = [part for part in [subheadline, description] if part]
    if text_parts:
        _elementor_append_widget_to_section(section, "text-editor", {"content": "\n\n".join(text_parts), "text_color": base_text}, text_column)
    if points:
        bullets = "".join(f"<li>{item}</li>" for item in points)
        _elementor_append_widget_to_section(section, "text-editor", {"content": f"<ul>{bullets}</ul>", "text_color": base_text}, text_column)
    if cta_text is not None and cta_url is not None:
        _elementor_append_widget_to_section(section, "button", {"text": cta_text, "link_url": cta_url}, text_column)
    if cta_secondary_text is not None and cta_secondary_url is not None:
        _elementor_append_widget_to_section(section, "button", {"text": cta_secondary_text, "link_url": cta_secondary_url}, text_column)
    if image_url is not None:
        _elementor_append_widget_to_section(section, "image", {"image_url": image_url, "align": "center"}, image_column)
    return _elementor_insert_elements(page_id, page_type, [section], position)

@mcp.tool()
def elementor_add_features_section(
    title: str,
    page_id: int = None,
    page_type: str = "pages",
    subtitle: str = None,
    features: list = None,
    columns: int = 3,
    style: str = "cards",
    bg_color: str = None,
    design_theme: str = "modern_light",
    position: str = "end",
) -> dict:
    """Add a features/services grid section. Choose style: 'cards' (elevated cards), 'minimal' (borderless), 'icon-left' (horizontal layout), 'numbered'"""
    bg = bg_color or ("#111827" if "dark" in design_theme else "#ffffff")
    sections: list[dict] = []
    if title is not None:
        sections.append(_elementor_make_heading_section(title, subtitle=subtitle, bg_color=bg, text_color="#ffffff" if "dark" in design_theme else None))
    items = list(features or [])
    if items:
        column_count = max(1, columns or len(items))
        cards_section = _elementor_make_section(columns=column_count, settings={"background_color": bg, "padding": {"top": "20", "bottom": "70"}})
        for index, feature in enumerate(items):
            entry = dict(feature or {})
            widget_settings = {k: v for k, v in {
                "icon": entry.get("icon"),
                "library": entry.get("library"),
                "title": entry.get("title") or entry.get("headline"),
                "description": entry.get("description") or entry.get("body"),
                "icon_color": entry.get("icon_color"),
                "icon_size": entry.get("icon_size"),
                "align": entry.get("align"),
                "view": style if style in {"cards", "minimal", "icon-left", "numbered"} else None,
                "link_url": entry.get("link_url"),
                "css_class": entry.get("css_class"),
            }.items() if v is not None}
            _elementor_append_widget_to_section(cards_section, "icon-box", widget_settings, index % column_count)
        sections.append(cards_section)
    return _elementor_insert_elements(page_id, page_type, sections, position)

