@mcp.tool()
def elementor_add_text_media_section(
    page_id: int,
    headline: str,
    body: str,
    page_type: str = "pages",
    badge: str = None,
    image_url: str = None,
    image_position: str = "right",
    points: list = None,
    cta_text: str = None,
    cta_url: str = None,
    bg_color: str = None,
    design_theme: str = "modern_light",
    position: str = "end",
) -> dict:
    """Add a text + image/media side-by-side section (alternating layout). imagePosition: 'right' or 'left'"""
    bg = bg_color or ("#ffffff" if "dark" not in design_theme else "#111827")
    section = _elementor_make_section(columns=2 if image_url is not None else 1, settings={"background_color": bg, "padding": {"top": "70", "bottom": "70"}})
    media_column = 1 if image_position == "right" and len(section.get("elements", [])) > 1 else 0
    text_column = 0 if media_column == 1 else 1 if len(section.get("elements", [])) > 1 else 0
    if badge is not None:
        _elementor_append_widget_to_section(section, "heading", {"text": badge, "tag": "h6", "color": "#ffffff" if bg == "#111827" else None}, text_column)
    _elementor_append_widget_to_section(section, "heading", {"text": headline, "tag": "h2", "color": "#ffffff" if bg == "#111827" else None}, text_column)
    _elementor_append_widget_to_section(section, "text-editor", {"content": body, "text_color": "#ffffff" if bg == "#111827" else None}, text_column)
    if points:
        bullets = "".join(f"<li>{item}</li>" for item in points)
        _elementor_append_widget_to_section(section, "text-editor", {"content": f"<ul>{bullets}</ul>", "text_color": "#ffffff" if bg == "#111827" else None}, text_column)
    if cta_text is not None and cta_url is not None:
        _elementor_append_widget_to_section(section, "button", {"text": cta_text, "link_url": cta_url}, text_column)
    if image_url is not None:
        _elementor_append_widget_to_section(section, "image", {"image_url": image_url, "align": "center"}, media_column)
    return _elementor_insert_elements(page_id, page_type, [section], position)

@mcp.tool()
def elementor_add_logo_bar(
    page_id: int,
    page_type: str = "pages",
    label: str = None,
    logos: list = None,
    bg_color: str = None,
    design_theme: str = "modern_light",
    position: str = "end",
) -> dict:
    """Add a client logos / trust badges / partners bar"""
    bg = bg_color or ("#ffffff" if "dark" not in design_theme else "#111827")
    sections: list[dict] = []
    if label is not None:
        sections.append(_elementor_make_heading_section(label, bg_color=bg, text_color="#ffffff" if bg == "#111827" else None, padding_top="40", padding_bottom="20"))
    items = list(logos or [])
    if items:
        logos_section = _elementor_make_section(columns=max(1, len(items)), settings={"background_color": bg, "padding": {"top": "20", "bottom": "40"}})
        for index, logo in enumerate(items):
            entry = logo if isinstance(logo, dict) else {"image_url": logo}
            widget_settings = {k: v for k, v in {
                "image_url": entry.get("image_url") or entry.get("url"),
                "image_alt": entry.get("alt") or entry.get("label"),
                "link_url": entry.get("link_url"),
                "align": "center",
            }.items() if v is not None}
            _elementor_append_widget_to_section(logos_section, "image", widget_settings, index)
        sections.append(logos_section)
    return _elementor_insert_elements(page_id, page_type, sections, position)

@mcp.tool()
def elementor_set_page_full_width(
    page_id: int,
    template: str = "elementor_canvas",
) -> dict:
    """Set an Elementor page to full width (removes sidebar, sets canvas or full-width template)"""
    return _wp().post(f"/wp/v2/pages/{page_id}", json={"template": template})

